// All values in MB.
const boxRamMB = 32 * 1024;
const sharedBuffersMB = 8 * 1024;
const connections = 350;
const workMemMB = 64;
const opsPerBackend = 3;
const perBackendOverheadMB = 10; // private memory: plan cache, libpq buffers, stack

function totalRamMB() {
  return sharedBuffersMB + connections * (workMemMB * opsPerBackend + perBackendOverheadMB);
}

const total = totalRamMB();
const oom = total > boxRamMB;
console.log('total_mb=' + total);
console.log('box_mb=' + boxRamMB);
console.log('oom=' + oom);
